#!/bin/sh
# ipa-netgroup-sync -- generated by freebsd-ipa-client (plugin netgroup-yp).
# Exports IPA hostgroups containing this host into the local NIS netgroup
# map so sudo can match +hostgroup entries. Served by ypserv on loopback
# only; ypbind is pinned to 127.0.0.1. Rewrites the map only on change.
set -eu
SYNC_HOST_FQDN="$HOST_FQDN"
SYNC_HOST_SHORT="$HOST_SHORT"
SYNC_NIS_DOMAIN="$NIS_DOMAIN"
SYNC_IPA_SERVER="$IPA_SERVER"
SYNC_IPA_REALM="$IPA_REALM"
SYNC_BASE_DN="$BASE_DN"
KEYTAB="/usr/local/etc/ipa/krb5.keytab"
SRC="$NETGROUP_FILE"
SYNC_YP_DIR="$YP_DIR"
KINIT=/usr/bin/kinit
KDESTROY=/usr/bin/kdestroy
LDAPSEARCH=/usr/local/bin/ldapsearch
MAKE=/usr/bin/make

CC="$(mktemp /tmp/krb5cc_yp_XXXXXX)" || exit 1
cleanup() { KRB5CCNAME="FILE:$CC" "$KDESTROY" >/dev/null 2>&1 || true; rm -f "$CC"; }
trap cleanup EXIT INT TERM
export KRB5CCNAME="FILE:$CC"
"$KINIT" -k -t "$KEYTAB" "host/$SYNC_HOST_FQDN@$SYNC_IPA_REALM" >/dev/null 2>&1 || exit 1

_tmp="$(mktemp /tmp/ypgroups_XXXXXX)" || exit 1
"$LDAPSEARCH" -Y GSSAPI -o ldif-wrap=no -H "ldap://$SYNC_IPA_SERVER" \
    -b "fqdn=$SYNC_HOST_FQDN,cn=computers,cn=accounts,$SYNC_BASE_DN" \
    -s base '(objectClass=ipaHost)' memberOf 2>/dev/null \
    | grep '^memberOf: cn=' | grep ',cn=hostgroups,' \
    | sed -E 's/^memberOf: cn=([^,]+),.*/\1/' | sort -u > "$_tmp"
{
    printf '# Generated by ipa-netgroup-sync from IPA hostgroups; do not edit.\n'
    while IFS= read -r _g; do
        [ -n "$_g" ] || continue
        printf '%s (%s,,%s) (%s,,%s)\n' "$_g" "$SYNC_HOST_FQDN" "$SYNC_NIS_DOMAIN" "$SYNC_HOST_SHORT" "$SYNC_NIS_DOMAIN"
    done < "$_tmp"
} > "$_tmp.done"
rm -f "$_tmp"
if [ -f "$SRC" ] && cmp -s "$SRC" "$_tmp.done"; then
    rm -f "$_tmp.done"
    exit 0
fi
cat "$_tmp.done" > "$SRC"
rm -f "$_tmp.done"
if pgrep -x ypserv >/dev/null 2>&1; then
    "$MAKE" -C "$SYNC_YP_DIR" "NETGROUP=$SRC" netgroup </dev/null >/dev/null 2>&1
fi
